// --- States, tabs & per-item actions --------------------------------------
let currentTab='toread';
const tabs=document.getElementById('tabs');
tabs.addEventListener('click', e=>{
  const t=e.target.closest('.tab'); if(!t) return;
  currentTab=t.dataset.state; setActiveTab(); renderList();
});
function setActiveTab(){
  [...tabs.querySelectorAll('.tab')].forEach(t=>t.classList.toggle('active', t.dataset.state===currentTab));
}
function updateCounts(){
  ['toread','done','archived'].forEach(s=>{
    document.getElementById('c-'+s).textContent = saved.filter(b=>b.state===s).length;
  });
}
const LABELS={toread:'To read', done:'Done', archived:'Archived'};
const EMPTY={
  toread:'Nothing to read right now. Saved links land here.',
  done:'Nothing marked done yet.',
  archived:'Nothing archived. Links you keep but tuck away appear here.'
};
function setState(id,s){ const b=saved.find(x=>x.id===id); if(b){ b.state=s; renderList(); } }
function editSaved(id){
  const b=saved.find(x=>x.id===id); if(!b) return;
  urlEl.value=b.url; pTitle.value=b.title; pDesc.value=b.desc;
  pSite.textContent=b.site; fav.textContent=b.letter;
  tags=[...b.tags]; renderTags(); document.getElementById('note').value=b.note;
  fetchbox.classList.remove('hidden','failed'); warnmsg.classList.add('hidden');
  autofilled.classList.add('hidden'); dupmsg.classList.remove('hidden');
  editingId=b.id; saveBtn.textContent='Update bookmark'; refreshSave();
  window.scrollTo({top:0, behavior:'smooth'});
}
function deleteSaved(id){ const i=saved.findIndex(x=>x.id===id); if(i>=0){ saved.splice(i,1); renderList(); } }

function renderList(){
  updateCounts();
  const items=saved.filter(b=>b.state===currentTab);
  if(!items.length){ list.innerHTML=`<div class="empty">${EMPTY[currentTab]}</div>`; return; }
  list.innerHTML='';
  items.forEach(b=>{
    const el=document.createElement('div');
    el.className='list-item';
    const tagsHtml=b.tags.map(t=>`<span class="chip">${t}</span>`).join('');
    // State-appropriate move actions
    let moves='';
    if(b.state!=='done')     moves+=`<button class="act" data-act="done">Mark done</button>`;
    if(b.state!=='toread')   moves+=`<button class="act" data-act="toread">Move to To read</button>`;
    if(b.state!=='archived') moves+=`<button class="act" data-act="archived">Archive</button>`;
    el.innerHTML=`
      <div class="fav">${b.letter}</div>
      <div style="flex:1">
        <div class="title"><a href="${b.url}" target="_blank" rel="noopener">${b.title}</a></div>
        <div class="site">${b.site}</div>
        ${b.note?`<div class="note">${b.note}</div>`:''}
        <div class="meta">${tagsHtml}</div>
        <div class="item-actions">
          ${moves}
          <button class="act" data-act="edit">Edit</button>
          <button class="act danger" data-act="delete">Delete</button>
        </div>
      </div>`;
    el.querySelectorAll('.act').forEach(btn=>btn.onclick=()=>{
      const a=btn.dataset.act;
      if(a==='edit') editSaved(b.id);
      else if(a==='delete') deleteSaved(b.id);
      else setState(b.id, a);
    });
    list.appendChild(el);
  });
}
