  if(total<=pageSize){ pager.classList.add('hidden'); return; }
  pager.classList.remove('hidden');
  pager.innerHTML=`
    <button ${page<=1?'disabled':''} data-nav="prev">‹ Previous</button>
    <span class="pinfo">Showing ${start+1}–${start+shown} of ${total} · page ${page} of ${totalPages}</span>
