// A simulated preview-image thumbnail (stands in for the page's real og:image).
function previewImage(host, letter){
  const hue=[...host].reduce((a,c)=>a+c.charCodeAt(0),0)%360;
  const svg=`<svg xmlns='http://www.w3.org/2000/svg' width='320' height='168'>
    <defs><linearGradient id='g' x1='0' y1='0' x2='1' y2='1'>
      <stop offset='0' stop-color='hsl(${hue},70%,55%)'/>
      <stop offset='1' stop-color='hsl(${(hue+40)%360},70%,42%)'/></linearGradient></defs>
    <rect width='320' height='168' fill='url(#g)'/>
    <text x='160' y='95' font-size='64' fill='white' font-family='sans-serif' text-anchor='middle' opacity='0.9'>${letter}</text>
    <text x='160' y='140' font-size='16' fill='white' font-family='sans-serif' text-anchor='middle' opacity='0.85'>${host}</text></svg>`;
  return 'data:image/svg+xml;utf8,'+encodeURIComponent(svg);
}
