  try { host = new URL(url).hostname.replace(/^www\./,''); } catch(e){ return {ok:false, host:""}; }
  if(/timeout|nometa|unreachable/.test(host)) return {ok:false, host};
  const known=CANNED[host];
  const nameGuess=host.split('.')[0].replace(/(^|\W)\w/g,c=>c.toUpperCase());
  const letter=(host[0]||'?').toUpperCase();
  const hasImage=!/noimage/.test(host);   // some pages provide no preview image
  return {
    ok:true, host,
    title: known?known.title:(nameGuess+" — page title"),
    desc:  known?known.desc:"A short description pulled from the page would appear here.",
    letter,
    favicon: `https://icons.duckduckgo.com/ip3/${host}.ico`,   // real site icon; falls back to the letter
    image: hasImage ? previewImage(host, letter) : null
  };
}
// Avatar HTML: real favicon with a letter fallback if the icon can't load.
function favHtml(b){
  if(b.favicon) return `<div class="fav"><img class="favimg" src="${b.favicon}" alt="" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'"><span class="favletter" style="display:none">${b.letter}</span></div>`;
  return `<div class="fav"><span class="favletter" style="display:flex">${b.letter}</span></div>`;
}

