const tagEntry=document.getElementById('tag-entry');
const tagsInput=document.getElementById('tags-input');
tagEntry.addEventListener('keydown', e=>{
  if(e.key==='Enter' && tagEntry.value.trim()){
    e.preventDefault();
    const t=tagEntry.value.trim();
    if(!tags.includes(t)){ tags.push(t); renderTags(); }
    tagEntry.value='';
  } else if(e.key==='Backspace' && !tagEntry.value && tags.length){ tags.pop(); renderTags(); }
});

input.new_string:
const tagEntry=document.getElementById('tag-entry');
const tagsInput=document.getElementById('tags-input');
const tagSuggest=document.getElementById('tag-suggest');
let sugList=[], sugActive=-1;

function tagCounts(){
  const m=new Map();
  saved.forEach(b=>b.tags.forEach(t=>m.set(t,(m.get(t)||0)+1)));
  return m;
}
function computeSuggestions(){
  const q=tagEntry.value.trim().toLowerCase();
  const counts=tagCounts();
  let all=[...counts.keys()].filter(t=>!tags.includes(t));
  if(q) all=all.filter(t=>t.toLowerCase().includes(q));
  all.sort((a,b)=> (counts.get(b)-counts.get(a)) || a.localeCompare(b));
  return all.slice(0,6).map(t=>({t, n:counts.get(t)}));
}
function renderSuggest(){
  sugList=computeSuggestions();
  const q=tagEntry.value.trim();
  const exactExists = sugList.some(s=>s.t.toLowerCase()===q.toLowerCase());
  if(!sugList.length && !(q && !exactExists)){ tagSuggest.classList.add('hidden'); return; }
  sugActive=-1;
  let html=sugList.map((s,i)=>`<div class="sug" data-i="${i}">${s.t}<span class="used">used ${s.n}×</span></div>`).join('');
  if(q && !exactExists) html+=`<div class="newnote">Press Enter to add “${q}” as a new tag</div>`;
  tagSuggest.innerHTML=html;
  tagSuggest.classList.remove('hidden');
  tagSuggest.querySelectorAll('.sug').forEach(el=>el.onmousedown=e=>{ e.preventDefault(); addTag(sugList[+el.dataset.i].t); });
}
function addTag(t){
  t=t.trim(); if(t && !tags.includes(t)){ tags.push(t); renderTags(); }
