const selpage=document.getElementById('selpage');
const bulkbar=document.getElementById('bulkbar');
selpage.addEventListener('change', ()=>{
  const ids=lastPageItems.map(b=>b.id);
  if(selpage.checked) ids.forEach(id=>selected.add(id));
  else ids.forEach(id=>selected.delete(id));
  renderList();
});
function syncSelPage(){
  const ids=lastPageItems.map(b=>b.id);
  const allSel = ids.length>0 && ids.every(id=>selected.has(id));
  selpage.checked=allSel;
  selpage.indeterminate = !allSel && ids.some(id=>selected.has(id));
}
function clearSelection(){ selected.clear(); renderList(); }
function selectedBookmarks(){ return saved.filter(b=>selected.has(b.id)); }
function renderBulkBar(){
  if(!selected.size){ bulkbar.classList.add('hidden'); bulkbar.innerHTML=''; return; }
  bulkbar.classList.remove('hidden');
  const matching=lastFiltered.length;
  const canSelectAll = matching>0 && lastFiltered.some(b=>!selected.has(b.id));
  const archivedView = currentTab==='archived';
  bulkbar.innerHTML=`
    <span class="bcount">${selected.size} selected</span>
    ${canSelectAll?`<button class="blink" data-b="all">Select all ${matching} in this view</button>`:''}
    <button class="blink" data-b="clear">Clear</button>
    <span class="sep"></span>
    <button class="act" data-b="addtag">Add tag…</button>
    <button class="act" data-b="removetag">Remove tag…</button>
    <button class="act" data-b="toread">Mark unread</button>
    <button class="act" data-b="done">Mark read</button>
    ${archivedView
      ? `<button class="act" data-b="restore">Restore</button>`
      : `<button class="act" data-b="archive">Archive</button>`}
    <button class="act danger" data-b="delete">Delete</button>`;
  bulkbar.querySelectorAll('[data-b]').forEach(btn=>btn.onclick=()=>bulkAction(btn.dataset.b));
}
function bulkAction(a){
  const sel=selectedBookmarks();
  switch(a){
    case 'all': lastFiltered.forEach(b=>selected.add(b.id)); renderList(); return;
    case 'clear': clearSelection(); return;
    case 'toread': sel.forEach(b=>b.status='toread'); break;
    case 'done':   sel.forEach(b=>b.status='done'); break;
    case 'archive':sel.forEach(b=>b.archived=true); break;
    case 'restore':sel.forEach(b=>b.archived=false); break;
    case 'delete':
      if(!confirm(`Delete ${sel.length} bookmark${sel.length===1?'':'s'} permanently?`)) return;
      sel.forEach(b=>{ const i=saved.findIndex(x=>x.id===b.id); if(i>=0) saved.splice(i,1); });
      selected.clear(); break;
    case 'addtag': return promptBulkTag('add');
    case 'removetag': return promptBulkTag('remove');
  }
  renderList();
}
function promptBulkTag(mode){
  const existing=bulkbar.parentElement.querySelector('.bulkform');
  if(existing) existing.remove();
  const form=document.createElement('div');
  form.className='bulkform';
  form.innerHTML=`<input type="text" placeholder="${mode==='add'?'Tag to add to':'Tag to remove from'} ${selected.size} selected" >
                  <button class="act" data-ok>${mode==='add'?'Add':'Remove'}</button>
                  <button class="act" data-cancel>Cancel</button>`;
  bulkbar.parentElement.appendChild(form);
  const inp=form.querySelector('input'); inp.focus();
  const apply=()=>{
    const t=inp.value.trim(); if(!t){ form.remove(); return; }
    selectedBookmarks().forEach(b=>{
      if(mode==='add'){ if(!b.tags.includes(t)) b.tags.push(t); }
      else { b.tags=b.tags.filter(x=>x!==t); }
    });
    form.remove(); renderList();
  };
  form.querySelector('[data-ok]').onclick=apply;
  form.querySelector('[data-cancel]').onclick=()=>form.remove();
  inp.onkeydown=e=>{ if(e.key==='Enter') apply(); if(e.key==='Escape') form.remove(); };
}

