// --- Saved searches --------------------------------------------------------
let savedSearches=[];
try{ savedSearches=JSON.parse(localStorage.getItem('bm_searches')||'[]'); }catch(e){}
let ssId = savedSearches.reduce((m,s)=>Math.max(m,s.id),0)+1;
const ssRow=document.getElementById('savedsearches');
function persistSearches(){ try{ localStorage.setItem('bm_searches', JSON.stringify(savedSearches)); }catch(e){} }
function applySavedSearch(s){
  currentTab=s.view; setActiveTab();
  searchEl.value=s.query; query=s.query; compileQuery();
  clearBtn.style.display = s.query.trim()?'inline-block':'none';
  page=1; renderList();
}
function renderSavedSearches(){
  let html = savedSearches.length ? `<span class="sslabel">Saved searches:</span>` : '';
  html += savedSearches.map(s=>
    `<span class="sschip" data-id="${s.id}"><button class="ssapply" title="${s.query} · in ${TAB_LABEL[s.view]}">${s.name}</button><button class="ssdel" aria-label="remove">×</button></span>`).join('');
  const q=query.trim();
  const canSave = q!=='' && !queryError && !savedSearches.some(s=>s.query===q && s.view===currentTab);
  if(canSave) html += `<button class="ssadd" id="ssadd">＋ Save this search</button>`;
  ssRow.innerHTML=html;
  ssRow.style.display = html? 'flex':'none';
  ssRow.querySelectorAll('.sschip').forEach(chip=>{
    const id=+chip.dataset.id;
    chip.querySelector('.ssapply').onclick=()=>applySavedSearch(savedSearches.find(s=>s.id===id));
    chip.querySelector('.ssdel').onclick=()=>{ savedSearches=savedSearches.filter(s=>s.id!==id); persistSearches(); renderSavedSearches(); };
  });
  const add=document.getElementById('ssadd');
  if(add) add.onclick=promptSaveSearch;
}
function promptSaveSearch(){
  const old=ssRow.querySelector('.bulkform'); if(old) old.remove();
  const form=document.createElement('div'); form.className='bulkform';
  form.innerHTML=`<input type="text" placeholder="Name this search" value="${query.trim().slice(0,40)}">
                  <button class="act" data-ok>Save</button><button class="act" data-cancel>Cancel</button>`;
  ssRow.appendChild(form);
  const inp=form.querySelector('input'); inp.focus(); inp.select();
  const ok=()=>{ const name=inp.value.trim(); if(!name){ form.remove(); return; }
    savedSearches.push({id:ssId++, name, query:query.trim(), view:currentTab});
    persistSearches(); renderSavedSearches();
  };
  form.querySelector('[data-ok]').onclick=ok;
  form.querySelector('[data-cancel]').onclick=()=>form.remove();
  inp.onkeydown=e=>{ if(e.key==='Enter') ok(); if(e.key==='Escape') form.remove(); };
}

function renderList(){
  updateCounts();
  renderSavedSearches();
  const inView=saved.filter(b=>inTab(b,currentTab));   // search stays within the current view

