// --- Import / export in standard bookmark HTML ----------------------------
function escAttr(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function exportHtml(){
  let out='<!DOCTYPE NETSCAPE-Bookmark-file-1>\n'+
    '<META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8">\n'+
    '<TITLE>Bookmarks</TITLE>\n<H1>Bookmarks</H1>\n<DL><p>\n';
  saved.forEach(b=>{
    const add=Math.floor((b.createdAt||Date.now())/1000);
    out+=`    <DT><A HREF="${escAttr(b.url)}" ADD_DATE="${add}"`+
         `${b.tags.length?` TAGS="${escAttr(b.tags.join(','))}"`:''}>${escAttr(b.title)}</A>\n`;
    if(b.note) out+=`    <DD>${escAttr(b.note)}\n`;
  });
  out+='</DL><p>\n';
  return out;
}
document.getElementById('export-btn').addEventListener('click', ()=>{
  const blob=new Blob([exportHtml()],{type:'text/html'});
  const a=document.createElement('a'); a.href=URL.createObjectURL(blob);
  a.download='bookmarks.html'; document.body.appendChild(a); a.click(); a.remove();
  URL.revokeObjectURL(a.href);
  document.getElementById('ie-msg').textContent=`Exported ${saved.length} bookmark${saved.length===1?'':'s'}.`;
});
function importHtml(text){
  const doc=new DOMParser().parseFromString(text,'text/html');
  const anchors=[...doc.querySelectorAll('a[href]')];
  let added=0, skipped=0;
  anchors.forEach(a=>{
    const url=a.getAttribute('href'); if(!/^https?:/i.test(url||'')) return;
    if(findSaved(url)){ skipped++; return; }
    const addAttr=a.getAttribute('add_date');
    const created= addAttr? parseInt(addAttr,10)*1000 : Date.now();
    const tagsAttr=a.getAttribute('tags')||'';
    const tgs= tagsAttr? tagsAttr.split(',').map(s=>s.trim()).filter(Boolean) : [];
    const dt=a.closest('dt'); const sib=dt&&dt.nextElementSibling;
    const note=(sib && sib.tagName==='DD') ? sib.textContent.trim() : '';
    let host=''; try{ host=new URL(url).hostname.replace(/^www\./,''); }catch(e){}
    saved.push({ id:nextId++, url, title:(a.textContent.trim()||url), desc:'', site:host,
      letter:(host[0]||'?').toUpperCase(), favicon:`https://icons.duckduckgo.com/ip3/${host}.ico`, image:null,
      tags:tgs, note, keepCopy:true, isPdf:isPdf(url), copyDate:Date.now(), ia:false, iaUrl:null,
      status:'toread', archived:false, createdAt:created });
    added++;
  });
  return {added, skipped};
}
document.getElementById('import-btn').addEventListener('click', ()=>document.getElementById('import-file').click());
document.getElementById('import-file').addEventListener('change', e=>{
  const file=e.target.files[0]; if(!file) return;
  const reader=new FileReader();
  reader.onload=()=>{
    const {added, skipped}=importHtml(reader.result);
    currentTab='toread'; page=1; setActiveTab(); renderList();
    document.getElementById('ie-msg').textContent=
      `Imported ${added} bookmark${added===1?'':'s'}`+(skipped?`, skipped ${skipped} already saved.`:'.');
  };
  reader.readAsText(file);
  e.target.value='';
});

renderList();
document.body.setAttribute('data-harness-ready','true');

