:root { --line:#e4e4e7; --muted:#71717a; --accent:#4f46e5; --bg:#fafafa; --warn:#b45309; --warnbg:#fffbeb; }
* { box-sizing:border-box; }
body { margin:0; font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif; color:#18181b; background:var(--bg); }
.wrap { max-width:820px; margin:0 auto; padding:0 24px; }
header { background:#fff; border-bottom:1px solid var(--line); padding:18px 0; }
.head { display:flex; justify-content:space-between; align-items:flex-start; gap:16px; flex-wrap:wrap; }
h1 { margin:0; font-size:19px; } .sub { margin:3px 0 0; color:var(--muted); font-size:13px; }
.topbar { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
.ie-msg { font-size:12px; color:#047857; }
main { padding:24px 0 60px; }
.card { background:#fff; border:1px solid var(--line); border-radius:12px; padding:20px; margin-bottom:20px; }
label { display:block; font-size:12px; font-weight:600; color:var(--muted); margin:14px 0 6px; text-transform:uppercase; letter-spacing:.03em; }
label:first-child { margin-top:0; }
.mdhint { font-weight:400; text-transform:none; letter-spacing:0; }
input[type=text],input[type=url],textarea,select { width:100%; padding:10px 12px; border:1px solid var(--line); border-radius:8px; font-size:14px; font-family:inherit; }
textarea { min-height:70px; resize:vertical; }
button { font:inherit; cursor:pointer; border-radius:8px; border:1px solid transparent; }
a.act { text-decoration:none; display:inline-block; }
.btn-primary { background:var(--accent); color:#fff; padding:10px 18px; font-weight:600; font-size:14px; }
.btn-primary:disabled { opacity:.5; cursor:not-allowed; }
.act { background:#fff; border:1px solid var(--line); padding:6px 12px; font-size:13px; color:#3f3f46; }
.act:hover { border-color:var(--accent); color:var(--accent); }
.act.danger:hover { border-color:#dc2626; color:#dc2626; }
.save-row { margin-top:18px; }
.hint { font-size:13px; margin-top:8px; }
.fetching { color:var(--muted); font-style:italic; }
.badurl { color:var(--warn); } .badurl code { background:#fef3c7; padding:1px 5px; border-radius:4px; }
.hidden { display:none; }
.dupmsg { margin-top:10px; padding:10px 14px; border-radius:8px; font-size:13px; background:#eef2ff; color:var(--accent); border:1px solid #c7d2fe; }
.fetchbox { margin-top:8px; padding:14px; background:var(--bg); border:1px dashed var(--line); border-radius:10px; }
.fetchbox.failed { background:var(--warnbg); border-color:#fde68a; }
.warnmsg { color:var(--warn); font-size:13px; margin-bottom:10px; }
.fetchhead { display:flex; gap:12px; align-items:center; }
.fav { width:36px; height:36px; border-radius:8px; background:var(--accent); color:#fff; display:flex; align-items:center; justify-content:center; font-weight:700; flex-shrink:0; font-size:15px; overflow:hidden; }
.fav .favimg { width:100%; height:100%; object-fit:contain; background:#fff; }
.fav .favletter { width:100%; height:100%; display:flex; align-items:center; justify-content:center; }
.site { color:var(--muted); font-size:12px; }
.autofilled { font-size:11px; color:var(--accent); font-weight:600; }
.preview-img { margin-top:10px; } .preview-img img { width:100%; max-width:320px; border-radius:8px; border:1px solid var(--line); display:block; }
.preview-img .noimg { font-size:12px; color:var(--muted); font-style:italic; }
.tags-wrap { position:relative; }
.tags-input { display:flex; flex-wrap:wrap; gap:6px; padding:8px; border:1px solid var(--line); border-radius:8px; }
.tags-input input { border:none; outline:none; flex:1; min-width:120px; padding:4px; font-size:14px; }
.chip { background:#eef2ff; color:var(--accent); font-size:12px; font-weight:600; padding:4px 8px; border-radius:6px; display:inline-flex; gap:6px; align-items:center; }
.chip button { background:none; border:none; color:var(--accent); cursor:pointer; padding:0; font-size:14px; line-height:1; }
.tag-suggest { position:absolute; left:0; right:0; top:100%; margin-top:4px; z-index:20; background:#fff; border:1px solid var(--line); border-radius:8px; box-shadow:0 6px 20px rgba(0,0,0,.08); overflow:hidden; }
.tag-suggest .sug { padding:8px 12px; font-size:14px; cursor:pointer; display:flex; justify-content:space-between; gap:8px; }
.tag-suggest .sug .used { color:var(--muted); font-size:12px; }
.tag-suggest .sug:hover, .tag-suggest .sug.active { background:#eef2ff; color:var(--accent); }
.tag-suggest .newnote { padding:8px 12px; font-size:12px; color:var(--muted); border-top:1px solid var(--line); }
.note-preview { margin-top:8px; padding:10px 12px; background:var(--bg); border:1px solid var(--line); border-radius:8px; font-size:13px; color:#3f3f46; }
.note-preview::before { content:'Preview'; display:block; font-size:11px; font-weight:700; color:var(--muted); text-transform:uppercase; letter-spacing:.03em; margin-bottom:6px; }
.md p { margin:.3em 0; } .md ul { margin:.3em 0; padding-left:1.2em; } .md h1,.md h2,.md h3 { margin:.4em 0; font-size:1.05em; }
.md code { background:#eef2ff; padding:1px 5px; border-radius:4px; font-size:.92em; } .md a { color:var(--accent); }
.chk { display:flex; align-items:flex-start; gap:8px; font-size:13px; color:#3f3f46; font-weight:400; text-transform:none; letter-spacing:0; margin:6px 0 0; cursor:pointer; }
.chk input { margin-top:2px; }
.searchrow { display:flex; gap:8px; align-items:center; margin-bottom:12px; }
.searchrow input { flex:1; }
.searchhint { font-size:13px; color:var(--muted); margin:-4px 0 10px; }
.savedsearches { display:none; flex-wrap:wrap; gap:6px; align-items:center; margin:4px 0 10px; }
.sslabel { font-size:12px; color:var(--muted); font-weight:600; margin-right:2px; }
.sschip { display:inline-flex; align-items:center; background:#f4f4f5; border:1px solid var(--line); border-radius:7px; overflow:hidden; }
.sschip .ssapply { background:none; border:none; padding:5px 6px 5px 10px; font-size:13px; font-weight:600; color:#3f3f46; cursor:pointer; }
.sschip .ssapply:hover { color:var(--accent); }
.sschip .ssdel { background:none; border:none; padding:5px 8px; color:var(--muted); cursor:pointer; font-size:14px; }
.sschip .ssdel:hover { color:#dc2626; }
.ssadd { background:none; border:1px dashed var(--line); border-radius:7px; padding:5px 10px; font-size:12px; color:var(--accent); font-weight:600; cursor:pointer; }
.bulkform { display:flex; gap:6px; align-items:center; margin-top:8px; }
.bulkform input { padding:8px 10px; border:1px solid var(--line); border-radius:7px; font-size:14px; }
.controls { display:flex; gap:16px; justify-content:flex-end; margin-bottom:6px; flex-wrap:wrap; }
.ctl { font-size:12px; color:var(--muted); font-weight:600; display:flex; align-items:center; gap:6px; margin:0; text-transform:none; letter-spacing:0; }
.ctl select { width:auto; font-size:13px; font-weight:400; color:#18181b; padding:6px 8px; }
.tabs { display:flex; gap:4px; margin-bottom:8px; border-bottom:1px solid var(--line); }
.tab { background:none; border:none; padding:10px 14px; font-size:14px; color:var(--muted); font-weight:600; border-bottom:2px solid transparent; margin-bottom:-1px; cursor:pointer; }
.tab.active { color:var(--accent); border-bottom-color:var(--accent); }
.count { display:inline-block; min-width:18px; padding:0 5px; margin-left:2px; font-size:11px; background:var(--bg); border-radius:9px; color:var(--muted); }
.tab.active .count { background:#eef2ff; color:var(--accent); }
.selrow { display:flex; align-items:center; gap:14px; flex-wrap:wrap; padding:4px 0 8px; }
.selall { font-size:13px; color:var(--muted); font-weight:600; display:flex; align-items:center; gap:6px; cursor:pointer; margin:0; text-transform:none; letter-spacing:0; }
.selall input { width:auto; }
.bulkbar { display:flex; align-items:center; gap:8px; flex-wrap:wrap; padding:8px 12px; background:#eef2ff; border:1px solid #c7d2fe; border-radius:8px; }
.bulkbar .bcount { font-size:13px; font-weight:700; color:var(--accent); }
.bulkbar .blink { font-size:12px; color:var(--accent); cursor:pointer; text-decoration:underline; background:none; border:none; }
.bulkbar .sep { width:1px; height:18px; background:#c7d2fe; }
.selbox { width:16px; height:16px; flex-shrink:0; cursor:pointer; margin-top:4px; }
.list-item { display:flex; gap:14px; align-items:flex-start; padding:16px 0; border-top:1px solid var(--line); }
.list-item:first-child { border-top:none; }
#list { font-size:14px; }
body[data-ts="s"] #list { font-size:12.5px; } body[data-ts="m"] #list { font-size:14px; } body[data-ts="l"] #list { font-size:16.5px; }
.list-item .title { font-weight:600; } #list .list-item .title { font-size:1.07em; }
.list-item .title a { color:inherit; text-decoration:none; }
#list .list-item .site { font-size:.86em; }
.list-item .note { color:#3f3f46; margin-top:6px; background:var(--bg); padding:8px 10px; border-radius:6px; } #list .list-item .note { font-size:.93em; }
.list-item .meta { margin-top:8px; display:flex; flex-wrap:wrap; gap:6px; }
#list .list-item .meta .chip { font-size:.82em; cursor:pointer; }
.list-item .meta .chip:hover { background:#e0e7ff; }
.item-actions { margin-top:10px; display:flex; flex-wrap:wrap; gap:6px; }
.thumb { width:120px; flex-shrink:0; } .thumb img { width:100%; border-radius:8px; border:1px solid var(--line); display:block; }
@media (max-width:560px){ .thumb { display:none; } }
.empty { color:var(--muted); text-align:center; padding:30px 0; font-size:14px; }
.pager { display:flex; align-items:center; justify-content:center; gap:12px; padding:14px 0 2px; margin-top:6px; border-top:1px solid var(--line); }
.pager .pinfo { font-size:13px; color:var(--muted); }
.pager button { font-size:13px; padding:6px 14px; }
.pager button:disabled { opacity:.4; cursor:not-allowed; }
.modal { position:fixed; inset:0; background:rgba(0,0,0,.45); display:flex; align-items:center; justify-content:center; z-index:50; padding:20px; }
.modal.hidden { display:none; }
.modal-card { background:#fff; border-radius:12px; max-width:640px; width:100%; max-height:85vh; display:flex; flex-direction:column; overflow:hidden; }
.modal-head { display:flex; justify-content:space-between; align-items:flex-start; gap:12px; padding:16px 20px; border-bottom:1px solid var(--line); }
.modal-title { font-weight:700; font-size:15px; } .modal-sub { font-size:12px; color:var(--muted); margin-top:2px; }
.modal-body { padding:20px; overflow:auto; }
.snap-note { font-size:12px; color:var(--warn); background:var(--warnbg); border:1px solid #fde68a; padding:8px 10px; border-radius:8px; margin-bottom:14px; }
.snap-actions a.act { margin-right:8px; }
</content>

